  --color-primary:     #4f6ef7;
  --color-primary-dark:#3a56d4;
  --color-text:        #1a1d23;
  --color-text-muted:  #5a6070;
  --color-error:       #c0392b;
  --color-error-bg:    #fdf2f2;
  --color-success:     #1a7f5a;
  --color-helper:      #5a6070;
  --radius:            10px;
  --shadow:            0 4px 24px rgba(0,0,0,.08);
  --transition:        180ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  z-index: 9999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--color-primary-dark); outline-offset: 2px; }

/* ── Page header ─────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
  max-width: 520px;
  width: 100%;
}
.page-header .logo {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.15rem;
  color: var(--color-primary);
  margin-bottom: 1.5rem;
  text-decoration: none;
}
.page-header .logo svg { width: 28px; height: 28px; }
.page-header h1 { font-size: 1.9rem; font-weight: 700; letter-spacing: -.02em; line-height: 1.25; }
.page-header p  { color: var(--color-text-muted); margin-top: .5rem; font-size: .975rem; }

/* ── Card ────────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2.25rem 2rem;
  width: 100%;
  max-width: 520px;
}

/* ── Form layout ─────────────────────────────────────────────── */
.contact-form { display: flex; flex-direction: column; gap: 1.375rem; }

.form-field { display: flex; flex-direction: column; gap: .35rem; }

.form-field label {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-mark {
  color: var(--color-error);
  margin-left: .15em;
  aria-hidden: true;
}

/* ── Inputs ──────────────────────────────────────────────────── */
.form-field input {
  width: 100%;
  padding: .65rem .85rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: 7px;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
  outline: none;
}

.form-field input::placeholder { color: #a0a8b8; }

.form-field input:hover:not(:disabled) { border-color: #a0a8b8; }

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(79,110,247,.18);
  /* transparent outline for forced-colors */
  outline: 3px solid transparent;
}

.form-field input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}
.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(192,57,43,.18);
}

/* ── Helper & error text ─────────────────────────────────────── */
.helper-text {
  font-size: .8rem;
  color: var(--color-helper);
  display: flex;
  align-items: center;
  gap: .3rem;
}

.error-message {
  font-size: .8rem;
  color: var(--color-error);
  display: none;
  align-items: center;
  gap: .3rem;
  font-weight: 500;
}
.error-message.visible { display: flex; }

.error-message svg,
.helper-text svg {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
}

/* ── Submit button ───────────────────────────────────────────── */
.btn-submit {
  margin-top: .25rem;
  padding: .75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 7px;
  cursor: pointer;
  transition: background var(--transition), transform 80ms ease, box-shadow var(--transition);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  outline: none;
}
.btn-submit:hover  { background: var(--color-primary-dark); }
.btn-submit:active { transform: scale(.98); }
.btn-submit:focus  {
  box-shadow: 0 0 0 3px rgba(79,110,247,.35);
  outline: 3px solid transparent;
}

/* ── Status banner ───────────────────────────────────────────── */
.form-status {
  border-radius: 7px;
  padding: .85rem 1rem;
  font-size: .9rem;
  font-weight: 500;
  display: none;
  align-items: flex-start;
  gap: .5rem;
}
.form-status.visible { display: flex; }
.form-status svg { flex-shrink: 0; width: 18px; height: 18px; margin-top: 1px; }

.form-status.success {
  background: #edf7f2;
  color: var(--color-success);
  border: 1.5px solid #b6e0ce;
}
.form-status.error {
  background: var(--color-error-bg);
  color: var(--color-error);
  border: 1.5px solid #f5c6c2;
}

/* ── Divider ─────────────────────────────────────────────────── */
.divider {
  height: 1px;
  background: var(--color-bg);
  margin: .25rem 0;
}

/* ── Required legend ─────────────────────────────────────────── */
.required-legend {
  font-size: .78rem;
  color: var(--color-text-muted);
  text-align: right;
}

/* ── Forced colors ───────────────────────────────────────────── */
@media (forced-colors: active) {
  .form-field input:focus,
  .btn-submit:focus { outline: 3px solid ButtonText; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonBorder; }
  .error-message { color: LinkText; }
}

/* ── Reflow @ 320 px ─────────────────────────────────────────── */
@media (max-width: 360px) {
  .card { padding: 1.5rem 1rem; }
  .page-header h1 { font-size: 1.5rem; }
}
