  --color-surface:     #ffffff;
  --color-border:      #d0d5dd;
  --color-border-focus:#4f6ef7;
  --color-primary:     #4f6ef7;
  --color-primary-dark:#3a56d4;
  --color-text:        #1a1d23;
  --color-text-muted:  #5a6070;
  --color-error:       #c0392b;
  --color-error-bg:    #fdf2f2;
  --color-success:     #1a7f5a;
  --color-helper:      #5a6070;
  --radius:            10px;
  --shadow:            0 4px 24px rgba(0,0,0,.08);
  --transition:        180ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  z-index: 9999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--color-primary-dark); outline-offset: 2px; }

/* ── Page header ─────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
  max-width: 520px;
  width: 100%;
}
.page-header .logo {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.15rem;
  color: var(--color-primary);
  margin-bottom: 1.5rem;
  text-decoration: none;
}
.page-header .logo svg { width: 28px; height: 28px; }
.page-header h1 { font-size: 1.9rem; font-weight: 700; letter-spacing: -.02em; line-height: 1.25; }
.page-header p  { color: var(--color-text-muted); margin-top: .5rem; font-size: .975rem; }

/* ── Card ────────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2.25rem 2rem;
  width: 100%;
  max-width: 520px;
}

/* ── Form layout ─────────────────────────────────────────────── */
.contact-form { display: flex; flex-direction: column; gap: 1.375rem; }

.form-field { display: flex; flex-direction: column; gap: .35rem; }

.form-field label {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-mark {
  color: var(--color-error);
  margin-left: .15em;
  aria-hidden: true;
}

/* ── Inputs ──────────────────────────────────────────────────── */
.form-field input {
  width: 100%;
  padding: .65rem .85rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: 7px;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
  outline: none;
}

.form-field input::placeholder { color: #a0a8b8; }

.form-field input:hover:not(:disabled) { border-color: #a0a8b8; }

.form-field input:focus {
  border-color: var(--color-border-focus);
