  outline: 3px solid transparent;
}

.form-field input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}
.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(192,57,43,.18);
}

/* ── Helper & error text ─────────────────────────────────────── */
.helper-text {
  font-size: .8rem;
  color: var(--color-helper);
  display: flex;
  align-items: center;
  gap: .3rem;
}

.error-message {
  font-size: .8rem;
  color: var(--color-error);
  display: none;
  align-items: center;
  gap: .3rem;
  font-weight: 500;
}
.error-message.visible { display: flex; }

.error-message svg,
.helper-text svg {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
}

/* ── Submit button ───────────────────────────────────────────── */
.btn-submit {
  margin-top: .25rem;
  padding: .75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 7px;
  cursor: pointer;
  transition: background var(--transition), transform 80ms ease, box-shadow var(--transition);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  outline: none;
}
.btn-submit:hover  { background: var(--color-primary-dark); }
.btn-submit:active { transform: scale(.98); }
.btn-submit:focus  {
  box-shadow: 0 0 0 3px rgba(79,110,247,.35);
  outline: 3px solid transparent;
}

/* ── Status banner ───────────────────────────────────────────── */
.form-status {
  border-radius: 7px;
  padding: .85rem 1rem;
  font-size: .9rem;
  font-weight: 500;
  display: none;
  align-items: flex-start;
  gap: .5rem;
}
.form-status.visible { display: flex; }
.form-status svg { flex-shrink: 0; width: 18px; height: 18px; margin-top: 1px; }

.form-status.success {
  background: #edf7f2;
  color: var(--color-success);
  border: 1.5px solid #b6e0ce;
}
.form-status.error {
  background: var(--color-error-bg);
  color: var(--color-error);
  border: 1.5px solid #f5c6c2;
}

/* ── Divider ─────────────────────────────────────────────────── */
.divider {
  height: 1px;
  background: var(--color-bg);
  margin: .25rem 0;
}

/* ── Required legend ─────────────────────────────────────────── */
.required-legend {
  font-size: .78rem;
  color: var(--color-text-muted);
  text-align: right;
}

/* ── Forced colors ───────────────────────────────────────────── */
@media (forced-colors: active) {
