+  if (!/^[+]?[\d\s\-().]{7,20}$/.test(trimmed)) {
+    return 'Please enter a valid phone number (e.g. (555) 555-5555).';
+  }
+  return null;
+}
+
+// ── Field state helpers ───────────────────────────────────────────────────────
+
+function setFieldError(fieldEl, errorMsg) {
+  const input = fieldEl.querySelector('input');
+  const errorEl = fieldEl.querySelector('.error-message');
+
+  if (errorMsg) {
+    input.setAttribute('aria-invalid', 'true');
+    errorEl.textContent = '';
+    // Rebuild with icon to keep markup clean via JS
+    const icon = createErrorIcon();
+    const span = document.createElement('span');
+    span.textContent = errorMsg;
+    errorEl.appendChild(icon);
+    errorEl.appendChild(span);
+    errorEl.classList.add('visible');
+  } else {
+    input.setAttribute('aria-invalid', 'false');
+    input.removeAttribute('aria-invalid');
+    errorEl.classList.remove('visible');
+    errorEl.textContent = '';
+  }
+}
