+// ── Validate-on-blur (only after first interaction) ───────────────────────────
+
+function attachBlurValidation(fieldEl, validator) {
+  const input = fieldEl.querySelector('input');
+  let touched = false;
+
+  input.addEventListener('blur', () => {
+    touched = true;
+    setFieldError(fieldEl, validator(input.value));
+  });
+
+  input.addEventListener('input', () => {
+    if (touched) {
+      setFieldError(fieldEl, validator(input.value));
+    }
+  });
+}
+
+// ── Form component ────────────────────────────────────────────────────────────
+
+function ContactForm() {
+  const form       = document.getElementById('contact-form');
+  const nameField  = document.getElementById('field-name');
+  const emailField = document.getElementById('field-email');
+  const phoneField = document.getElementById('field-phone');
+  const statusEl   = document.getElementById('form-status');
+
+  attachBlurValidation(nameField,  validateFullName);
+  attachBlurValidation(emailField, validateEmail);
+  attachBlurValidation(phoneField, validatePhone);
+
+  form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    // Run all validators
+    const nameError  = validateFullName(nameField.querySelector('input').value);
+    const emailError = validateEmail(emailField.querySelector('input').value);
+    const phoneError = validatePhone(phoneField.querySelector('input').value);
+
+    setFieldError(nameField,  nameError);
+    setFieldError(emailField, emailError);
+    setFieldError(phoneField, phoneError);
+
+    const firstError = nameError ? nameField
+                     : emailError ? emailField
+                     : phoneError ? phoneField
+                     : null;
+
+    if (firstError) {
+      firstError.querySelector('input').focus();
