+    span.textContent = message;
+
+    statusEl.textContent = '';
+    statusEl.appendChild(iconSvg);
+    statusEl.appendChild(span);
+  }
+
+  function createSuccessIcon() {
+    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
+    svg.setAttribute('aria-hidden', 'true');
+    svg.setAttribute('viewBox', '0 0 16 16');
+    svg.setAttribute('fill', 'none');
+    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
+    path.setAttribute('fill', 'currentColor');
+    path.setAttribute('d', 'M8 1a7 7 0 1 0 0 14A7 7 0 0 0 8 1Zm3.28 5.78-4 4a.75.75 0 0 1-1.06 0l-2-2a.75.75 0 1 1 1.06-1.06l1.47 1.47 3.47-3.47a.75.75 0 1 1 1.06 1.06Z');
+    svg.appendChild(path);
+    return svg;
+  }
+}
